document.head.insertAdjacentHTML('beforeend','<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#27348B"><meta name="robots" content="noindex,nofollow,noarchive"><link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/losco78/losco@main/dimaro-trip-2026/style.css">');document.title='Dimaro 2026';document.body.innerHTML=`<div id="login"><div class="loginbox"><div style="font-size:34px">🔒</div><h1>Dimaro 2026</h1><p>Pagina privata. Inserisci email e codice.</p><div class="field"><label>Email</label><input id="email" type="email" value="loosco@gmail.com"></div><div class="field"><label>Codice</label><input id="key" type="password"></div><button id="go" class="btn primary" style="width:100%">Accedi</button><div id="err" class="err"></div></div></div><header><div class="head"><div><h1 id="title">Dimaro 2026</h1><p id="sub">Documento di viaggio interattivo</p></div><div id="status">Accesso richiesto</div></div></header><main><div id="notice" class="notice">Caricamento…</div><div class="tools"><span id="last" class="muted"></span><div class="actions"><button id="share" class="btn ghost">🔗</button><button id="refresh" class="btn ghost">↻</button><button id="out" class="btn ghost">Esci</button></div></div><div class="tabs"><button class="on" data-v="it">Itinerario</button><button data-v="food">Mangiare</button><button data-v="contacts">Contatti</button><button data-v="notes">Note</button></div><section id="it" class="view on"><div id="summary" class="summary"><span class="muted">Nessuna scelta effettuata.</span></div><div id="daynav" class="daynav"></div><div id="days" class="days"></div></section><section id="food" class="view"><h2>Dove mangiare</h2><div class="panel muted">Pranzo e cena sono sempre previsti. Nei box giornalieri scegliete il locale e segnate se è stato prenotato.</div><div id="restaurants" class="cards" style="margin-top:10px"></div></section><section id="contacts" class="view"><h2>Contatti utili</h2><div id="cards" class="cards"></div></section><section id="notes" class="view"><h2>Note condivise</h2><textarea id="note" placeholder="Decisioni, prenotazioni, dubbi…"></textarea><p class="muted">Salvataggio automatico e sincronizzazione ogni pochi secondi.</p></section></main><nav class="bottom"><button class="on" data-v="it">🗓️<br>Itinerario</button><button data-v="food">🍽️<br>Mangiare</button><button data-v="contacts">📇<br>Contatti</button><button data-v="notes">📝<br>Note</button></nav>`;const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/gh/losco78/losco@main/dimaro-trip-2026/app.js';document.body.appendChild(s);